            [
                ['rating' => 5, 'comment' => '初めて訪問しましたが、スープの完成度が非常に高くて驚きました。豚骨と鶏ガラをブレンドしたスープは、深みがあるのにしつこくない。麺は自家製の中太ストレートで、歯切れの良さが抜群です。具材のメンマも自家製らしく、シャキシャキした食感が楽しめます。行列は覚悟ですが、回転は早いのでそこまで待ちません。駅チカでアクセスも良いです。'],
                ['rating' => 4, 'comment' => 'ランチタイムに訪問。お昼のセットメニューが充実していてコスパが良い。ラーメンに半チャーハンと餃子がついて1000円以下はお得です。スープは醤油豚骨でコクがありながらもバランスの良い味。麺の量もちょうど良い。気になった点としては、ランチ時は非常に混雑していて騒がしい。ゆっくり食べたい人は少し時間をずらすのがおすすめです。'],
                ['rating' => 3, 'comment' => '普通に美味しいラーメンです。特に際立った個性はないですが、安定した味で外れがありません。誰にでもおすすめできる万人向けの一杯。スープの濃さもちょうどよく、麺の茹で加減も良い。ただ、近隣にも同レベルのお店があるので、わざわざ足を運ぶ決め手がもう一つ欲しい。サイドメニューのチャーハンは美味しかったです。接客も普通で可もなく不可もなく。'],
                ['rating' => 2, 'comment' => '期待して行きましたが、スープがぬるかったのが残念。ラーメンは熱々が命だと思うので、この一点で大きくマイナスです。味自体は悪くないのですが、温度のせいで脂が固まりかけていて口当たりが悪かった。麺は普通。量も少なく感じました。値段を考えるともう少し頑張ってほしい。立地は良いし内装も綺麗なので、基本的な部分を改善すれば良いお店になりそうです。'],
                ['rating' => 3, 'comment' => '二度目の来店。前回と比べて味が少し変わった気がします。前は美味しかったスープのコクが薄くなったような。日によるのかもしれませんが少し残念。麺は相変わらず美味しいし、チャーシューも柔らかくて良い。あと前回なかった辛みそトッピングが増えていたので試してみましたが、これは美味しかった。メニューの改良は続けているようなので、今後に期待します。'],
            ],
        ];

        $restaurants = Restaurant::orderBy('id')->get();

        foreach ($restaurants as $index => $restaurant) {
            // レビューセットをローテーション
            $setIndex = $index % count($reviewSets);
            $reviews = $reviewSets[$setIndex];

            foreach ($reviews as $i => $reviewData) {
                Review::create([
                    'restaurant_id' => $restaurant->id,
                    'user_id' => $userIds[$i % count($userIds)],
                    'rating' => $reviewData['rating'],
                    'comment' => $reviewData['comment'],
                ]);
            }

            // 要約を生成
            $summaryService = app(ReviewSummaryService::class);
            $summary = $summaryService->generate($restaurant);
            $restaurant->update(['review_summary' => $summary]);

            echo "✓ {$restaurant->name}: 5件のレビューと要約を生成\n";
        }
    }
}
